import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Input,
  Select,
  SearchInput,
  SearchTextInput,
  LinPageLayout,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import type { ActiveCompanyItem } from '@linm-soft-org/linm-web-common-components';
import { Tag, Popconfirm } from '@/components/common';
import { useAppDispatch } from '../../../store/hooks';
import { fpcService } from '../../../services/fpc/service';
import { createCompanySearchConfig } from '../../../components/search/companySearchConfig';
import { useFpcPermissions } from '../../../utils/fpcPermissionCode';
import { planVoucherListPage, type PlanVoucherDraftDto } from '../../../services/fpc/types';
import styles from './PlanVoucherList.module.css';

const TEST_ID = 'plan-voucher-list';
const PAGE_SIZE = 20;
const LIST_PATH = '/tc/ke-hoach';

const MONTH_LABELS: Record<number, string> = {
  1: 'Tháng 1', 2: 'Tháng 2', 3: 'Tháng 3', 4: 'Tháng 4',
  5: 'Tháng 5', 6: 'Tháng 6', 7: 'Tháng 7', 8: 'Tháng 8',
  9: 'Tháng 9', 10: 'Tháng 10', 11: 'Tháng 11', 12: 'Tháng 12',
};

const MONTH_OPTIONS = [
  { value: '', label: 'Tất cả' },
  ...Array.from({ length: 12 }, (_, i) => ({
    value: String(i + 1),
    label: MONTH_LABELS[i + 1],
  })),
];

const formatMoney = (v: number) =>
  new Intl.NumberFormat('vi-VN', {
    style: 'currency',
    currency: 'VND',
    maximumFractionDigits: 0,
  }).format(v);

function formatViDate(iso?: string | null): string {
  if (!iso) return '—';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '—';
  return d.toLocaleDateString('vi-VN');
}

const PlanVoucherList: React.FC = () => {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const now = new Date();
  const { canManagePlanVoucher, canDeletePlanVoucher } = useFpcPermissions();

  const [items, setItems] = useState<PlanVoucherDraftDto[]>([]);
  const [totalCount, setTotalCount] = useState(0);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(1);

  const [planYear, setPlanYear] = useState(now.getFullYear());
  const [planMonth, setPlanMonth] = useState('');
  const [branchCode, setBranchCode] = useState('');
  const [selectedCompany, setSelectedCompany] = useState<ActiveCompanyItem | null>(null);
  const [searchDraft, setSearchDraft] = useState('');
  const [search, setSearch] = useState('');

  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [rowMenu, setRowMenu] = useState<{
    x: number;
    y: number;
    item: PlanVoucherDraftDto;
  } | null>(null);

  const companySearchConfig = useMemo(() => createCompanySearchConfig(), []);
  const selectedItem = useMemo(
    () => items.find(i => i.id === selectedId) ?? null,
    [items, selectedId],
  );

  const fetchList = useCallback(async () => {
    setLoading(true);
    try {
      const raw = await fpcService.getPlanVoucherList({
        planYear,
        planMonth: planMonth === '' ? undefined : parseInt(planMonth, 10),
        branchCode: branchCode || undefined,
        search: search.trim() || undefined,
        page,
        pageSize: PAGE_SIZE,
      });
      const result = planVoucherListPage(raw, page, PAGE_SIZE);
      setItems(result.items);
      setTotalCount(result.totalCount);
      if (selectedId && !result.items.some(i => i.id === selectedId)) {
        setSelectedId(null);
      }
    } catch {
      setItems([]);
      setTotalCount(0);
      dispatchAppToast(dispatch, {
        message: 'Không thể tải danh sách phiếu kế hoạch',
        type: 'error',
      });
    } finally {
      setLoading(false);
    }
  }, [dispatch, planYear, planMonth, branchCode, search, page, selectedId]);

  useEffect(() => {
    const t = window.setTimeout(() => {
      void fetchList();
    }, 0);
    return () => window.clearTimeout(t);
  }, [fetchList]);

  useEffect(() => {
    if (!rowMenu) return undefined;
    const close = () => setRowMenu(null);
    window.addEventListener('click', close);
    return () => window.removeEventListener('click', close);
  }, [rowMenu]);

  const resetPage = useCallback(() => setPage(1), []);

  const handleSearch = useCallback(() => {
    setSearch(searchDraft.trim());
    resetPage();
  }, [searchDraft, resetPage]);

  const handleBranchChange = (item: ActiveCompanyItem | null) => {
    setBranchCode(item?.code ?? item?.id ?? '');
    setSelectedCompany(item);
    resetPage();
  };

  const handleDelete = async (id: string) => {
    try {
      await fpcService.deletePlanVoucher(id);
      dispatchAppToast(dispatch, { message: 'Đã xóa phiếu kế hoạch', type: 'success' });
      if (selectedId === id) setSelectedId(null);
      void fetchList();
    } catch {
      dispatchAppToast(dispatch, { message: 'Lỗi khi xóa phiếu kế hoạch', type: 'error' });
    }
  };

  const openView = (item: PlanVoucherDraftDto) => {
    navigate(`${LIST_PATH}/${item.id}`);
  };

  const voucherToolbar = useMemo(
    () => ({
      testIdPrefix: TEST_ID,
      onRefresh: () => void fetchList(),
      canCreate: canManagePlanVoucher,
      onCreate: () => navigate(`${LIST_PATH}/new`),
      canView: !!selectedItem,
      onView: () => selectedItem && navigate(`${LIST_PATH}/${selectedItem.id}`),
      canEdit: !!selectedItem && canManagePlanVoucher,
      onEdit: () => selectedItem && navigate(`${LIST_PATH}/${selectedItem.id}`),
    }),
    [canManagePlanVoucher, fetchList, navigate, selectedItem],
  );

  return (
    <div
      className={styles.voucherListRoot}
      data-voucher-list-page
      data-testid={`${TEST_ID}-page`}
    >
      <LinPageLayout
        kind="voucher"
        testIdPrefix={TEST_ID}
        pageClassName={styles.voucherListPage}
        header={{
          title: 'Danh sách phiếu kế hoạch',
          hint: 'Lập và theo dõi kế hoạch thu / chi theo kỳ',
          titleIconClass: 'fas fa-calendar-alt',
        }}
        voucherToolbar={voucherToolbar}
        listTitle="Danh sách phiếu"
        listRowMenuHelp
        filterMaxWidthPx={1100}
        showTableLoading={loading}
        filters={(
          <>
            <div className={styles.filterField}>
              <Input
                label="Năm"
                type="number"
                value={String(planYear)}
                onChange={e => {
                  setPlanYear(parseInt(e.target.value, 10) || now.getFullYear());
                  resetPage();
                }}
                data-testid={`${TEST_ID}-filter-year`}
              />
            </div>
            <div className={styles.filterField}>
              <Select
                label="Tháng"
                value={planMonth}
                onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {
                  setPlanMonth(e.target.value);
                  resetPage();
                }}
                options={MONTH_OPTIONS}
                data-testid={`${TEST_ID}-filter-month`}
              />
            </div>
            <div className={styles.filterFieldWide}>
              <SearchInput
                config={companySearchConfig}
                value={branchCode}
                primaryDisplay={selectedCompany?.code}
                secondaryDisplay={selectedCompany?.name}
                onChange={item => handleBranchChange(item as ActiveCompanyItem)}
                onClear={() => handleBranchChange(null)}
                label="Chi nhánh"
                placeholder="Tất cả chi nhánh..."
                data-testid={`${TEST_ID}-filter-branch`}
              />
            </div>
            <div className={styles.filterFieldWide}>
              <SearchTextInput
                label="Tìm kiếm"
                placeholder="Số phiếu / diễn giải..."
                value={searchDraft}
                onChange={setSearchDraft}
                onSearch={handleSearch}
                testId={`${TEST_ID}-search-text`}
              />
            </div>
          </>
        )}
        footerPagination={{
          page,
          pageSize: PAGE_SIZE,
          totalCount,
          onPageChange: setPage,
          itemLabel: 'phiếu',
        }}
      >
        {items.length === 0 && !loading ? (
          <div className={styles.empty}>
            <i className="fas fa-inbox" />
            <p>
              {search.trim() || branchCode || planMonth
                ? 'Không tìm thấy phiếu kế hoạch phù hợp bộ lọc'
                : 'Chưa có phiếu kế hoạch'}
            </p>
            {canManagePlanVoucher && (
              <button
                type="button"
                className={styles.emptyCreateBtn}
                onClick={() => navigate(`${LIST_PATH}/new`)}
                data-testid={`${TEST_ID}-empty-create`}
              >
                Tạo phiếu đầu tiên
              </button>
            )}
          </div>
        ) : (
          <table className={styles.table} data-testid={`${TEST_ID}-grid`}>
            <thead className={styles.stickyHead}>
              <tr>
                <th className={styles.thStt}>STT</th>
                <th>Số phiếu</th>
                <th>Ngày lập</th>
                <th>Kỳ kế hoạch</th>
                <th>Chi nhánh</th>
                <th className={styles.colRight}>Tổng KH</th>
                <th className={styles.colRight}>Thực tế</th>
                <th className={styles.colRight}>Dòng</th>
                <th>Trạng thái</th>
                <th className={styles.thActions} />
              </tr>
            </thead>
            <tbody>
              {items.map((item, idx) => (
                <tr
                  key={item.id}
                  className={selectedId === item.id ? styles.rowSelected : undefined}
                  onClick={() => setSelectedId(item.id)}
                  onDoubleClick={() => openView(item)}
                  onContextMenu={e => {
                    e.preventDefault();
                    setSelectedId(item.id);
                    setRowMenu({ x: e.clientX, y: e.clientY, item });
                  }}
                  data-testid={`${TEST_ID}-row-${item.id}`}
                >
                  <td className={styles.cellStt}>{(page - 1) * PAGE_SIZE + idx + 1}</td>
                  <td><strong>{item.code}</strong></td>
                  <td>{formatViDate(item.voucherDate)}</td>
                  <td>
                    <Tag>{MONTH_LABELS[item.planMonth] ?? `T${item.planMonth}`}/{item.planYear}</Tag>
                  </td>
                  <td>{item.branchCode || '—'}</td>
                  <td className={styles.colRight}>{formatMoney(item.totalPlanned)}</td>
                  <td className={styles.colRight}>{formatMoney(item.totalActual)}</td>
                  <td className={styles.colRight}>{item.lineCount}</td>
                  <td>
                    <Tag color={item.status === 'Draft' ? 'blue' : 'green'}>
                      {item.status === 'Draft' ? 'Nháp' : 'Đã ghi'}
                    </Tag>
                  </td>
                  <td className={styles.cellActions} onClick={e => e.stopPropagation()}>
                    <button
                      type="button"
                      className={styles.linkBtn}
                      title="Xem"
                      onClick={() => openView(item)}
                    >
                      <i className="fas fa-eye" />
                    </button>
                    {canManagePlanVoucher && (
                      <button
                        type="button"
                        className={styles.linkBtn}
                        title="Sửa"
                        onClick={() => openView(item)}
                      >
                        <i className="fas fa-edit" />
                      </button>
                    )}
                    {canDeletePlanVoucher && (
                      <Popconfirm
                        title="Xóa phiếu kế hoạch này?"
                        onConfirm={() => handleDelete(item.id)}
                      >
                        <button
                          type="button"
                          className={`${styles.linkBtn} ${styles.linkBtnDanger}`}
                          title="Xóa"
                        >
                          <i className="fas fa-trash" />
                        </button>
                      </Popconfirm>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
            {totalCount > 0 && (
              <tfoot>
                <tr className={styles.totalRow}>
                  <td colSpan={10}>Tổng cộng: {totalCount} phiếu</td>
                </tr>
              </tfoot>
            )}
          </table>
        )}
      </LinPageLayout>

      {rowMenu && (
        <div
          className={styles.rowMenu}
          style={{ left: rowMenu.x, top: rowMenu.y }}
          data-testid={`${TEST_ID}-row-menu`}
          onClick={e => e.stopPropagation()}
        >
          <button type="button" onClick={() => { openView(rowMenu.item); setRowMenu(null); }}>
            Xem
          </button>
          {canManagePlanVoucher && (
            <button
              type="button"
              onClick={() => {
                openView(rowMenu.item);
                setRowMenu(null);
              }}
            >
              Sửa
            </button>
          )}
          {canDeletePlanVoucher && (
            <button
              type="button"
              className={styles.rowMenuDanger}
              onClick={() => {
                void handleDelete(rowMenu.item.id);
                setRowMenu(null);
              }}
            >
              Xóa
            </button>
          )}
        </div>
      )}
    </div>
  );
};

export default PlanVoucherList;
